 async function addManagerAdmin(){const name=newAdminName.trim(),phone=newAdminPhone.replace(/\D/g,"");if(name.length<2||!/^[6-9]\d{9}$/.test(phone)){toast("Enter a name and valid 10-digit Indian mobile number starting with 6–9.");return}if(managerAdmins.some(a=>a.phone===phone)){toast("That mobile number is already on the access list.");return}const next=[...managerAdmins,{name,phone,role:newAdminRole}];setAdminSaving(true);try{const r=await saveManagerAdminsPin({data:{admins:next,token:managerUser.token}});if(!r.ok){toast(r.message||"Could not save access list.");return}setManagerAdmins(r.admins);setNewAdminName("");setNewAdminPhone("");if(r.initialPins?.length){const issued=r.initialPins.map((x:any)=>`${x.name} (+91 ${x.phone}): ${x.pin}`).join("\n");window.alert(`Temporary sign-in PIN\n\n${issued}\n\nShare this PIN securely. The user must change it after signing in.`);toast("Access saved and temporary PIN generated.")}else toast("Manager access updated.")}catch{toast("Could not save manager access. Please try again.")}finally{setAdminSaving(false)}}
 async function removeManagerAdmin(phone:string){if(phone==="7200352252"){toast("The primary owner admin cannot be removed.");return}const next=managerAdmins.filter(a=>a.phone!==phone);setAdminSaving(true);try{const r=await saveManagerAdminsPin({data:{admins:next,token:managerUser.token}});if(!r.ok){toast(r.message||"Could not update access list.");return}setManagerAdmins(r.admins);toast("Access removed.")}catch{toast("Could not update access list.")}finally{setAdminSaving(false)}}
 async function resetManagerPin(phone:string){const value=window.prompt("Set a temporary 4-digit PIN. The user must change it after signing in.","");if(value===null)return;if(!/^\d{4}$/.test(value)){toast("PIN must be exactly 4 digits.");return}setAdminSaving(true);try{const r=await managerResetPin({data:{token:managerUser.token,phone,newPin:value}});if(!r.ok){toast(r.message||"PIN reset failed.");return}const fresh=await getManagerAdminsPin({data:{token:managerUser.token}});if(fresh.ok)setManagerAdmins(fresh.admins);toast(r.message)}catch{toast("PIN reset failed. Please try again.")}finally{setAdminSaving(false)}}
 async function saveOnboardingConfig(){setOnboardingSaving(true);try{const r=await savePropertyOnboardingConfig({data:{token:managerUser.token,property:onboardingConfigProperty,mandatoryFields:onboardingMandatoryFields as any,mandatoryDocuments:onboardingMandatoryDocuments as any,contactPhone:propertyContactPhone}});if(!r.ok){toast(r.message||"Could not save onboarding configuration.");return}toast(r.message)}catch{toast("Could not save onboarding configuration.")}finally{setOnboardingSaving(false)}}
